#include <iostream>

struct Node {
    int data;
    Node* next;
    Node* child;

    Node(int val) {
        data = val;
        next = nullptr;
        child = nullptr;
    }
};

// Helper function to merge two sorted vertical lists
Node* mergeTwoLists(Node* a, Node* b) {
    // If one list is empty, return the other
    if (a == nullptr) return b;
    if (b == nullptr) return a;

    Node* result;

    // Pick the smaller value and recurse for the rest
    if (a->data < b->data) {
        result = a;
        result->child = mergeTwoLists(a->child, b);
    } else {
        result = b;
        result->child = mergeTwoLists(a, b->child);
    }

    // Ensure the next pointer is always null for flattened nodes
    result->next = nullptr;
    return result;
}

// Main function to flatten the list
Node* flatten(Node* root) {
    // Base case: If list is empty or has no next column
    if (root == nullptr || root->next == nullptr) {
        return root;
    }

    // Recurse to the rightmost column
    root->next = flatten(root->next);

    // Merge current column with the flattened right side
    root = mergeTwoLists(root, root->next);

    return root;
}
